-- ============================================================================
-- V-160 يعني ثلاثة أشياء على هذا الموقع، وأحدها يُحصّل 11,604 ليرة
-- ============================================================================
-- البند الخامس من أمر العمل.
--
--   security_codes.V160          «تجميد عنوان»
--   identity-kimlik-iptal-v160   «إبطال الكملك (İptal) … (V-160)»
--   frozen-id-problem            «تجميد القيود (V-160 / إيقاف)»
--
-- والموقع يعرف أيّها الصحيح. صفحة syria-turkey-border-crossings-2026، 453 قراءة،
-- تقولها بالحرف: «راجعنا جدول الأكواد المدقَّق عندنا (125 كوداً) فوجدنا أنّ V-160
-- هو تجميد عنوان لا إبطال بطاقة». كتبَت تمريرةٌ سابقة من هذا التدقيق ذلك التصحيح
-- ولم تعد إلى الصفحة التي كانت تصحّحها — فالموقع ينشر الردّ والدعوى جنباً إلى جنب.
--
-- ── والمال ─────────────────────────────────────────────────────────────
--
-- حقل how_to_remove في الكود V160، بالعربية والتركية:
--
--   «يُرفع عند تثبيت العنوان بعد مراجعة إدارة الهجرة وبعد دفع الغرامة التي تبلغ
--    11604 ليرات حسب آخر التحديثات من ادارة الهجرة»
--
-- بلا أداة وبلا تاريخ، و«آخر التحديثات» ليست إسناداً. وهو أخطر من رقمٍ بلا مصدر
-- في موضع آخر، لأنّ src/app/codes/[code]/page.tsx يعرض how_to_remove حرفياً
-- بوصفه acceptedAnswer في سكيما FAQPage — أي أنّ «ادفع 11,604 ليرة» يُقدَّم
-- إلى جوجل جواباً مباشراً، وباللغتين.
--
-- وفي المقابل يسعّر consultant_scenarios.syrian-fix-address — وهو السطح الذي
-- يغلب عند التعارض — الإجراءَ نفسه بـ«مجاناً».
--
-- والذي أمكن التحقّق منه، من نشرة بيان العنوان لدى القنصلية العامة في سالزبورغ
-- (mfa.gov.tr) المحدَّثة في 18/5/2026، لعام 2026:
--
--   «adres bildirim yükümlülüğünü süresi içinde yerine getirmeyenlere 814,00 TL,
--    gerçeğe aykırı adres beyanında bulunanlara ise 17.051,00 TL idari para
--    cezası uygulanacaktır»
--
-- فلا 11,604 ولا رسمَ رفعِ كود: كلتاهما غرامة إدارية بالمادة 68 من القانون 5490
-- تفرضها مديرية النفوس. ولم نجد في أي مصدر أوّلي رسماً منشوراً لرفع V-160،
-- فصارت الصفحة تقول ذلك بدل أن تملأ الفراغ برقم.
--
-- وتكرّر فخّ «الصفحة الرسمية القديمة» للمرّة الثالثة في هذا التدقيق: ثلاث صفحات
-- على nvi.gov.tr في هذا الموضوع بعينه متجمّدة عند أرقام 2015 و2017
-- (480/963 ليرة و51/1.038 ليرة) وبلا تاريخ على الصفحة. النطاق الحكومي ليس ختم
-- تاريخ.
--
-- ── وما يتغيّر ─────────────────────────────────────────────────────────
--
--   security_codes.V160          يُحذف ادّعاء الرسم بالعربية والتركية، ويحلّ
--                                محلّه الإجراء الحقيقي وأرقام 5490 الحقيقية
--   frozen-id-problem            119 حرفاً، وهي الصفحة الوحيدة التي أصابت في
--                                V-160 — تُبنى لتكون الصفحة التي كان ينبغي أن تكون
--   identity-kimlik-iptal-v160   يخرج V-160 من عنوانها؛ موضوعها الإبطال وهو غيره
--   syrian-fix-address           «مجاناً» تصير دقيقة
--
-- والإصلاح المرافق في الشيفرة: صفحة /forms كانت تعرض «عريضة إزالة أكواد المنع
-- الأمنية (G-87, V-160)» تُنزِّل لائحةَ الجمارك التركية من ملفات مدرّس جامعي،
-- على مضيفٍ لم يعد يُحَلّ أصلاً. وبفحص بقية القائمة: واحدٌ من خمسة تنزيلات كان
-- يقدّم الوثيقة التي يعد بها اسمه.
--
-- آمن لإعادة التشغيل.
-- ============================================================================

UPDATE security_codes SET
    how_to_remove = 'يُرفع الكود بإثبات عنوانك من جديد: احجز موعد تحديث بيانات في مديرية الهجرة بولايتك، واحضر بما يثبت سكنك فعلاً في العنوان (عقد إيجار مسجَّل أو فاتورة خدمات باسمك)، ويُرفع القيد بعد التحقّق. ولا نعرف رسماً منشوراً يُدفع مقابل رفع هذا الكود بعينه — فإن طلب منك أحد مبلغاً بوصفه «رسم رفع الكود» فاطلب سنده المكتوب. أمّا الغرامات الإدارية المتعلّقة بالعنوان فهي غير ذلك تماماً: تفرضها مديرية النفوس بموجب المادة 68 من قانون خدمات النفوس رقم 5490، ومقاديرها لعام 2026 هي 814 ليرة لمن لم يبلّغ عن عنوانه في المهلة، و17,051 ليرة لمن أدلى ببيان عنوان غير صحيح. وهاتان تُدفعان للنفوس ولا تُدفعان لرفع كود.',
    how_to_remove_tr = 'Kod, adresin yeniden tespitiyle kaldırılır: ilinizdeki Göç İdaresinden bilgi güncelleme randevusu alın ve adreste fiilen oturduğunuzu gösteren belgeyle (kayıtlı kira sözleşmesi veya adınıza fatura) başvurun; doğrulamadan sonra kısıtlama kaldırılır. Bu kodun kaldırılması için yayımlanmış herhangi bir ücret tespit edilememiştir — size «kod kaldırma ücreti» adı altında bir meblağ söylenirse yazılı dayanağını isteyin. Adresle ilgili idari para cezaları ise bambaşkadır: 5490 sayılı Nüfus Hizmetleri Kanununun 68 inci maddesi uyarınca nüfus müdürlüğünce uygulanır ve 2026 için adres bildirim yükümlülüğünü süresinde yerine getirmeyenlere 814,00 TL, gerçeğe aykırı adres beyanında bulunanlara 17.051,00 TL olarak belirlenmiştir. Bunlar nüfus müdürlüğüne ödenir, bir kodu kaldırmak için değil.'
WHERE code = 'V160' AND how_to_remove LIKE '%11604%';

UPDATE articles SET
    title = 'كود V-160 (تجميد العنوان): لماذا يُوضع، وكيف يُرفع، وكم يكلّف فعلاً',
    details = '<p>«تجميد العنوان» هو ما يقابل الكود <strong>V-160</strong> في سجلّ إدارة الهجرة، واسمه بالتركية <strong>Adres Dondurma</strong>. ويُوضع في حالتين: أن تزور الشرطة عنوانك المسجَّل فلا تجدك فيه، أو أن تُضبط خارج ولاية تسجيلك بلا إذن سفر.</p><h2>ما ليس عليه — وهذا أهمّ من تعريفه</h2><p>يخلط كثيرون بين ثلاثة أشياء، ويكلّف الخلط مالاً:</p><ul><li><strong>V-160 ليس إبطالاً للكملك.</strong> بطاقتك لا تُلغى بهذا الكود؛ قيدك يُجمَّد حتى يُثبَّت عنوانك. وإلغاء الحماية المؤقتة إجراء آخر تصدره الولاية، وله سببه ومسطرته.</li><li><strong>وليس كوداً أمنياً.</strong> تصنيفه في جدولنا «إداري» لا «أمني»، فلا تعامله معاملة G-87 ولا تشترِ له «حلّاً أمنياً».</li><li><strong>ولا نعرف له رسم رفع منشوراً.</strong> راجعنا المصادر الرسمية فلم نجد مبلغاً مقرَّراً يُدفع مقابل رفع هذا الكود بعينه. فمن طلب منك مالاً بوصفه «رسم رفع الكود» فاطلب سنده المكتوب قبل أن تدفع.</li></ul><h2>والغرامات التي قد تسمع عنها — ما هي فعلاً</h2><p>هناك غرامات إدارية تخصّ العنوان، لكنّها ليست رسم رفعِ كود. تفرضها <strong>مديرية النفوس</strong> بموجب المادة 68 من قانون خدمات النفوس رقم 5490، ومقاديرها لعام 2026:</p><ul><li>عدم التبليغ عن العنوان في المهلة: <strong>814 ليرة</strong>.</li><li>الإدلاء ببيان عنوان غير صحيح: <strong>17,051 ليرة</strong>.</li></ul><p>وتُدفعان للنفوس، وقد لا تُفرضان عليك أصلاً. أمّا الأرقام التي تتداولها الصفحات بوصفها «غرامة الكود» فلم نجد لها سنداً منشوراً، ونبّهنا على ذلك في صفحة الكود نفسها.</p><h2>لماذا يستحقّ المعالجة فوراً</h2><p>التجميد يوقف ما هو معلَّق على القيد — المواعيد والخدمات والمساعدات — إلى أن يُرفع. والأثقل أنّ التخلّف عن واجب التبليغ عن العنوان ثلاث مرّات متتالية دون عذر يجيز للولاية إلغاء حمايتك المؤقتة (المادة 12/3 من لائحة الحماية المؤقتة). ومهلة التبليغ عن تغيير العنوان <strong>عشرون يوم عمل</strong> — لا يوماً تقويمياً — بالمادة 33/2(د) من اللائحة والمادة 50/3 من القانون 5490.</p><p>ومع ذلك، لا يجوز تقييد <strong>التعليم والصحة الطارئة</strong> بحال (المادة 35/2).</p><p style="margin-top:1.2rem;">وللتفصيل: <a href="/codes/V160">صفحة الكود V-160</a> • <a href="/article/address-registration-closed">الحي المغلق أمام تسجيل الأجانب</a> • <a href="/article/travel-permit">إذن السفر بين الولايات</a></p>',
    steps = ARRAY['احجز موعد «تحديث بيانات» في مديرية الهجرة بولايتك فوراً — التأخير يزيد التعقيد ولا يخفّفه.', 'ثبّت عنوانك في النفوس قبل الموعد إن استطعت، فوثيقة العنوان هي ما يُبنى عليه رفع القيد.', 'احضر بما يثبت سكنك فعلاً: عقد إيجار مسجَّل أو فاتورة خدمات باسمك — لا صورة عقد غير مسجَّل.', 'اسأل صراحةً عن سبب وضع الكود واطلبه مكتوباً؛ فسبب «لم يُعثر عليه» يُعالَج غير سبب «ضُبط خارج ولايته».', 'وإن طُلب منك مبلغ: اطلب سنده المكتوب واسم الغرامة. غرامة النفوس تُدفع للنفوس بإيصال، ولا تُدفع نقداً لأحد.', 'تابع بعد المراجعة حتى يظهر رفع القيد في النظام، ولا تكتفِ بوعدٍ شفهي.']::text[], tips = ARRAY['V-160 تجميد عنوان لا إبطال بطاقة — ومن يخبرك بغير ذلك يبيعك حلّاً لمشكلة لا تملكها.', 'لا رسم منشوراً لرفع الكود؛ وغرامتا العنوان (814 و17,051 ليرة) تخصّان النفوس لا رفع الكود.', 'مهلة التبليغ عن تغيير العنوان عشرون يوم عمل، لا شهر ولا عشرون يوماً تقويمياً.', 'التخلّف ثلاث مرّات متتالية عن واجب التبليغ يجيز إلغاء الحماية المؤقتة — وهذا الخطر الحقيقي.', 'التعليم والصحة الطارئة لا يجوز تقييدهما مهما كان وضع قيدك.', 'كن في المنزل عند كشف العنوان إن أمكن، أو اترك من يفتح ويشرح — أكثر الحالات تبدأ من زيارة لم يفتح فيها أحد.']::text[], documents = ARRAY['بطاقة الحماية المؤقتة (الكملك)', 'عقد إيجار مسجَّل أو سند ملكية', 'فاتورة خدمات (كهرباء/ماء/غاز) باسمك', 'وثيقة العنوان (Yerleşim Yeri Belgesi) إن استخرجتها']::text[],
    fees = 'لا نعرف رسماً منشوراً يُدفع مقابل رفع الكود، وموعد تحديث البيانات مجاني. والغرامات الإدارية المتعلّقة بالعنوان تفرضها النفوس بالمادة 68 من القانون 5490: 814 ليرة لعدم التبليغ في المهلة، و17,051 ليرة لبيان عنوان غير صحيح (مقادير 2026).',
    warning = 'لا تدفع مبلغاً بوصفه «رسم رفع الكود» قبل أن تطلب سنده المكتوب — لم نجد لهذا الرسم أثراً في أي مصدر رسمي. وحملة التحقّق من العناوين مستمرّة، والتخلّف ثلاث مرّات متتالية عن واجب التبليغ يجيز للولاية إلغاء حمايتك المؤقتة.',
    source = 'جدول الأكواد المدقَّق على /codes (125 كوداً) + قانون خدمات النفوس 5490 م.50 و68 + لائحة الحماية المؤقتة م.12/3 و33/2(د) و35/2 + نشرة بيان العنوان لدى القنصلية العامة في سالزبورغ (mfa.gov.tr) المحدَّثة في 18/5/2026',
    last_update = CURRENT_DATE
WHERE slug = 'frozen-id-problem';

UPDATE articles SET
    title = 'إبطال الكملك (İptal): الأسباب الشائعة وكيفية إعادة التفعيل',
    details = replace(details, 'أحياناً تُستخدم تسميات مثل “V-160” في بعض السياقات الإجرائية، لكن المهم عملياً هو:', 'وتصحيحٌ لازم: <strong>V-160 ليس إبطالاً للكملك</strong> — هو كود «تجميد عنوان» (Adres Dondurma) يُوضع حين لا يُعثر عليك في عنوانك المسجَّل أو تُضبط خارج ولايتك بلا إذن سفر، وقيدك يُجمَّد ولا تُلغى بطاقتك. فإن كان ما تراه على ملفك هو V-160 فموضعه <a href="/article/frozen-id-problem">صفحة تجميد العنوان</a> لا هذه الصفحة. أمّا الإبطال فسببه ومسطرته غير ذلك، والمهم فيه عملياً هو:'),
    last_update = CURRENT_DATE
WHERE slug = 'identity-kimlik-iptal-v160' AND title LIKE '%V-160%';

UPDATE consultant_scenarios SET
    cost = 'موعد تحديث البيانات مجاني، ولا نعرف رسماً منشوراً يُدفع مقابل رفع الكود نفسه. وما قد يُفرض عليك شيء آخر: غرامة إدارية عن العنوان بالمادة 68 من القانون 5490، تفرضها النفوس ومقاديرها لعام 2026 هي 814 ليرة لعدم التبليغ في المهلة و17,051 ليرة لبيان عنوان غير صحيح. فإن طُلب منك مبلغ بوصفه «رسم رفع الكود» فاطلب سنده المكتوب.', last_update = '2026-08'
WHERE id = 'syrian-fix-address' AND cost = 'مجاناً';

-- ═══════════════════════════════════════════════════════════════════════════
-- التحقّق — كل صفّ true
SELECT 'V160 fee claim removed' AS البند,
       (how_to_remove NOT LIKE '%11604%' AND how_to_remove_tr NOT LIKE '%11604%'
        AND how_to_remove LIKE '%5490%') AS سليم
FROM security_codes WHERE code = 'V160'
UNION ALL
SELECT 'frozen-id-problem rebuilt',
       (length(details) > 1500 AND details LIKE '%ليس إبطالاً للكملك%'
        AND coalesce(array_length(steps,1),0) >= 3)
FROM articles WHERE slug = 'frozen-id-problem'
UNION ALL
SELECT 'iptal page no longer claims V-160',
       (title NOT LIKE '%V-160%' AND details LIKE '%صفحة تجميد العنوان%')
FROM articles WHERE slug = 'identity-kimlik-iptal-v160'
UNION ALL
SELECT 'scenario cost precise', (cost NOT IN ('مجاناً') AND cost LIKE '%5490%')
FROM consultant_scenarios WHERE id = 'syrian-fix-address';
